const handleAdminDelete   = (type, id) => handleAdminSuspend(type, id);

// ── Crear sheet ───────────────────────────────────────────────────────────
const [createSheetOpen, setCreateSheetOpen] = useState(false);
const [nudgeModal, setNudgeModal] = useState(null); // { type: 'producto-nuevo'|'producto-usado-limite'|... }

// Lee el rol del perfil guardado
const userRole = (() => {
  try {
    const uid = firebaseUser?.uid;
    if (!uid) return 'usuario';
    const raw = localStorage.getItem(`lokal-user-profile:${uid}`);
    return raw ? (JSON.parse(raw).role || 'usuario') : 'usuario';
  } catch { return 'usuario'; }
})();

const canPostNewProduct  = ['emprendimiento', 'empresa'].includes(userRole);
const canPostUsedProduct = true; // todos pueden, con límite

// ─── Mini sheet "¿Qué querés crear?" ─────────────────────────────────────
const CreateSheet = () => {
  if (!createSheetOpen) return null;
  const options = [
    {
      icon: Package,
      color: 'bg-brand/10 text-brand',
      title: 'Publicar pedido',
      desc: 'Pedí algo y las tiendas te responden',
      action: () => { setCreateSheetOpen(false); setEditingDemanda(null); navigate('crear'); },
    },
    {
      icon: Tag,
      color: 'bg-purple-100 text-purple-600',
      title: 'Vender producto usado',
      desc: 'Publicá algo que ya no usás',
      action: () => {
        setCreateSheetOpen(false);
        // TODO: navegar a screen de venta — por ahora nudge si llegó al límite
        alert('Próximamente: publicar producto usado');
      },
    },
    {
      icon: Store,
      color: 'bg-amber-100 text-amber-600',
      title: 'Vender producto nuevo',
      desc: canPostNewProduct ? 'Publicá un producto de tu negocio' : 'Para emprendimientos y empresas',
      action: () => {
        setCreateSheetOpen(false);
        if (!canPostNewProduct) {
          setNudgeModal({ type: 'producto-nuevo' });
        } else {
          alert('Próximamente: publicar producto nuevo');
        }
      },
      locked: !canPostNewProduct,
    },
  ];

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/40 z-40 backdrop-blur-sm"
        onClick={() => setCreateSheetOpen(false)}
      />
      {/* Sheet */}
      <div className="fixed bottom-0 left-0 right-0 z-50 bg-white dark:bg-slate-900 rounded-t-3xl shadow-2xl px-5 pt-4 pb-8 animate-slide-up"
        style={{ paddingBottom: 'calc(env(safe-area-inset-bottom) + 2rem)' }}
      >
        {/* Handle */}
        <div className="w-10 h-1 bg-slate-200 dark:bg-white/10 rounded-full mx-auto mb-5" />
        <p className="text-base font-black text-slate-900 dark:text-white mb-4">¿Qué querés crear?</p>
        <div className="space-y-2.5">
          {options.map(({ icon: Icon, color, title, desc, action, locked }) => (
            <button
              key={title}
              onClick={action}
              className={`w-full flex items-center gap-4 p-4 rounded-2xl border transition-all text-left ${
                locked
                  ? 'border-slate-100 dark:border-white/5 bg-slate-50 dark:bg-white/3 opacity-70'
                  : 'border-slate-100 dark:border-white/10 bg-white dark:bg-white/5 hover:bg-slate-50 dark:hover:bg-white/8 active:scale-[0.98]'
              }`}
            >
              <div className={`w-11 h-11 rounded-xl flex items-center justify-center shrink-0 ${color}`}>
                <Icon size={22} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-bold text-slate-900 dark:text-white text-sm">{title}</p>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{desc}</p>
              </div>
              {locked && (
                <span className="text-[10px] font-bold bg-amber-100 text-amber-600 dark:bg-amber-500/20 dark:text-amber-400 px-2 py-1 rounded-full shrink-0">
                  Subir nivel
                </span>
              )}
            </button>
          ))}
        </div>
      </div>
    </>
  );
};

// ─── Modal de nudge de upgrade ────────────────────────────────────────────
const NudgeModal = () => {
  if (!nudgeModal) return null;

  const NUDGES = {
    'producto-nuevo': {
      icon: Store,
      iconColor: 'text-amber-500',
      iconBg: 'bg-amber-50 dark:bg-amber-500/10',
      title: 'Para productos nuevos',
      desc: 'Vender productos nuevos es para emprendimientos y empresas. ¡El registro es gratis y te da mucho más alcance!',
      actions: [
        {
          label: 'Ser Emprendimiento — gratis',
          style: 'bg-slate-900 dark:bg-white text-white dark:text-slate-900',
          onClick: () => { setNudgeModal(null); /* TODO: abrir flujo upgrade de rol */ alert('Próximamente: upgrade a Emprendimiento'); },
        },
        {
          label: 'Ahora no',
          style: 'border border-slate-200 dark:border-white/10 text-slate-600 dark:text-slate-400',
          onClick: () => setNudgeModal(null),
        },
      ],
    },
    'producto-usado-limite': {
      icon: Package,
      iconColor: 'text-purple-500',
      iconBg: 'bg-purple-50 dark:bg-purple-500/10',
      title: 'Llegaste al límite',
      desc: 'Podés tener hasta 3 productos de segunda mano como usuario. Subí a Emprendimiento (gratis) para publicar hasta 10.',
      actions: [
        {
          label: 'Subir a Emprendimiento — gratis',
          style: 'bg-slate-900 dark:bg-white text-white dark:text-slate-900',
          onClick: () => { setNudgeModal(null); alert('Próximamente: upgrade a Emprendimiento'); },
        },
        {
          label: 'Ahora no',
          style: 'border border-slate-200 dark:border-white/10 text-slate-600 dark:text-slate-400',
          onClick: () => setNudgeModal(null),
        },
      ],
    },
  };

  const n = NUDGES[nudgeModal.type];
  if (!n) return null;
  const Icon = n.icon;

  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-50 backdrop-blur-sm" onClick={() => setNudgeModal(null)} />
      <div className="fixed inset-x-4 top-1/2 -translate-y-1/2 z-50 bg-white dark:bg-slate-900 rounded-3xl shadow-2xl p-6 max-w-sm mx-auto">
        <div className={`w-14 h-14 rounded-2xl ${n.iconBg} flex items-center justify-center mx-auto mb-4`}>
          <Icon size={28} className={n.iconColor} />
        </div>
        <h3 className="text-lg font-black text-slate-900 dark:text-white text-center mb-2">{n.title}</h3>
        <p className="text-sm text-slate-500 dark:text-slate-400 text-center leading-relaxed mb-6">{n.desc}</p>
        <div className="space-y-2.5">
          {n.actions.map(({ label, style, onClick }) => (
            <button key={label} onClick={onClick}
              className={`w-full py-3.5 rounded-2xl font-bold text-sm transition-all ${style}`}>
              {label}
            </button>
          ))}
        </div>
      </div>
    </>
  );
};

