// ─── Vender Producto Screen ──────────────────────────────────────────────
const VenderProductoScreen = () => {
  const [condicion, setCondicion] = React.useState('usado');
  const [form, setForm] = React.useState({ titulo: '', descripcion: '', precio: '', categoryId: null, contactoWhatsapp: '' });
  const [fotos, setFotos] = React.useState([]);
  const [fotoPreviews, setFotoPreviews] = React.useState([]);
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState(null);
  const fotoInputRef = React.useRef(null);

  const canPostNew = canPostNewProduct;
  const isNew = condicion === 'nuevo';

  const handleFoto = (e) => {
    const files = Array.from(e.target.files || []).slice(0, 4 - fotos.length);
    files.forEach(f => {
      const reader = new FileReader();
      reader.onload = ev => setFotoPreviews(p => [...p, ev.target.result]);
      reader.readAsDataURL(f);
      setFotos(p => [...p, f]);
    });
  };

  const removeFoto = (i) => {
    setFotos(p => p.filter((_, idx) => idx !== i));
    setFotoPreviews(p => p.filter((_, idx) => idx !== i));
  };

  const handleSubmit = async () => {
    if (!form.titulo.trim()) { setError('El título es obligatorio'); return; }
    if (isNew && !canPostNew) { setNudgeModal({ type: 'producto-nuevo' }); return; }
    setSaving(true); setError(null);
    try {
      // Upload fotos primero si las hay
      let fotoUrls = [];
      if (fotos.length > 0) {
        const uploadPromises = fotos.map(async (file) => {
          const fd = new FormData();
          fd.append('file', file);
          const res = await apiFetch(`${API_BASE}/upload`, { method: 'POST', body: fd, authRequired: true });
          if (!res.ok) throw new Error('Error subiendo foto');
          const d = await res.json();
          return d.url;
        });
        fotoUrls = await Promise.all(uploadPromises);
      }

      const res = await apiFetch(`${API_BASE}/ofertas`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          vendedorId: firebaseUser.uid,
          vendedorNombre: firebaseUser.displayName || '',
          vendedorRol: userRole,
          condicion,
          titulo: form.titulo,
          descripcion: form.descripcion,
          precio: form.precio ? Number(form.precio) : null,
          categoryId: form.categoryId,
          fotos: fotoUrls,
          contactoWhatsapp: form.contactoWhatsapp,
        }),
        authRequired: true,
      });
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        if (res.status === 403 && d.error?.includes('Límite')) {
          setNudgeModal({ type: condicion === 'nuevo' ? 'producto-nuevo' : 'producto-usado-limite' });
          return;
        }
        throw new Error(d.error || 'Error al publicar');
      }
      navRoot('mis-productos');
    } catch (e) {
      setError(e.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f7f8fa] dark:bg-[#0a0d16] pb-28">
      {/* Header */}
      <div className="sticky top-0 z-20 bg-white dark:bg-[#0f172a] border-b border-slate-200 dark:border-white/10 px-4 py-3 flex items-center gap-3">
        <button onClick={goBack} className="p-2 -ml-2 rounded-xl hover:bg-slate-100 dark:hover:bg-white/5 transition-colors">
          <ArrowLeft size={20} className="text-slate-700 dark:text-white" />
        </button>
        <h1 className="font-black text-slate-900 dark:text-white text-base flex-1">Publicar producto</h1>
        <button
          onClick={handleSubmit}
          disabled={saving || !form.titulo.trim()}
          className="bg-brand text-white text-sm font-bold px-4 py-2 rounded-xl disabled:opacity-50 flex items-center gap-2"
        >
          {saving && <Loader2 size={14} className="animate-spin" />}
          Publicar
        </button>
      </div>

      <div className="max-w-lg mx-auto px-4 pt-5 space-y-5">
        {/* Condición toggle */}
        <div className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/10 p-4">
          <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-3">¿Qué vas a vender?</p>
          <div className="flex gap-2">
            {[
              { id: 'usado', label: '♻️ Producto usado', desc: 'Artículo de segunda mano' },
              { id: 'nuevo', label: '✨ Producto nuevo', desc: canPostNew ? 'Para tu negocio' : 'Solo emprendimientos', locked: !canPostNew },
            ].map(({ id, label, desc, locked }) => (
              <button
                key={id}
                onClick={() => {
                  if (locked) { setNudgeModal({ type: 'producto-nuevo' }); return; }
                  setCondicion(id);
                }}
                className={`flex-1 rounded-xl border-2 p-3 text-left transition-all ${
                  condicion === id
                    ? 'border-brand bg-brand-muted dark:bg-brand/10'
                    : locked
                      ? 'border-slate-100 dark:border-white/5 opacity-60'
                      : 'border-slate-200 dark:border-white/10 hover:border-slate-300'
                }`}
              >
                <p className="text-sm font-bold text-slate-900 dark:text-white">{label}</p>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{desc}</p>
                {locked && <span className="text-[10px] font-bold text-amber-600 bg-amber-50 dark:bg-amber-500/10 px-2 py-0.5 rounded-full mt-1 inline-block">Subir nivel</span>}
              </button>
            ))}
          </div>
        </div>

        {/* Fotos */}
        <div className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/10 p-4">
          <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-3">Fotos <span className="text-slate-400 font-normal normal-case">(hasta 4)</span></p>
          <div className="flex gap-2 flex-wrap">
            {fotoPreviews.map((src, i) => (
              <div key={i} className="relative w-20 h-20">
                <img src={src} className="w-full h-full object-cover rounded-xl" alt="" />
                <button onClick={() => removeFoto(i)} className="absolute -top-1.5 -right-1.5 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center">
                  <X size={10} />
                </button>
              </div>
            ))}
            {fotoPreviews.length < 4 && (
              <button onClick={() => fotoInputRef.current?.click()}
                className="w-20 h-20 rounded-xl border-2 border-dashed border-slate-300 dark:border-white/20 flex flex-col items-center justify-center gap-1 hover:border-brand transition-colors">
                <Camera size={20} className="text-slate-400" />
                <span className="text-[10px] text-slate-400">Agregar</span>
              </button>
            )}
          </div>
          <input ref={fotoInputRef} type="file" accept="image/*" multiple className="hidden" onChange={handleFoto} />
        </div>

        {/* Datos */}
        <div className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/10 p-4 space-y-4">
          <div>
            <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Título *</label>
            <input
              value={form.titulo}
              onChange={e => setForm(f => ({ ...f, titulo: e.target.value }))}
              placeholder={condicion === 'usado' ? 'Ej: Bicicleta MTB rodado 26' : 'Ej: Remera oversize negra talle M'}
              className="w-full mt-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl px-4 py-3 text-sm outline-none focus:border-brand transition-all"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Descripción</label>
            <textarea
              value={form.descripcion}
              onChange={e => setForm(f => ({ ...f, descripcion: e.target.value }))}
              placeholder="Estado, medidas, características importantes..."
              rows={3}
              className="w-full mt-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl px-4 py-3 text-sm outline-none focus:border-brand transition-all resize-none"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Precio</label>
            <div className="flex items-center mt-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl px-4 py-3 gap-2">
              <span className="text-slate-500 dark:text-slate-400 text-sm font-semibold">$</span>
              <input
                type="number"
                value={form.precio}
                onChange={e => setForm(f => ({ ...f, precio: e.target.value }))}
                placeholder="0"
                className="flex-1 bg-transparent text-sm outline-none text-slate-900 dark:text-white"
              />
            </div>
          </div>
          <div>
            <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2 block">Categoría</label>
            <CategoryPicker
              value={form.categoryId}
              onChange={id => setForm(f => ({ ...f, categoryId: id }))}
              placeholder="Seleccioná una categoría"
            />
          </div>
        </div>

        {/* Contacto */}
        <div className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/10 p-4 space-y-3">
          <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Contacto</p>
          <div className="flex items-center gap-3 p-3 bg-green-50 dark:bg-green-500/10 rounded-xl border border-green-200 dark:border-green-500/20">
            <MessageSquare size={18} className="text-green-600 shrink-0" />
            <div className="flex-1">
              <p className="text-sm font-semibold text-slate-800 dark:text-white">Chat interno Lokal</p>
              <p className="text-xs text-slate-500 dark:text-slate-400">Los interesados te escriben por la app</p>
            </div>
            <div className="w-4 h-4 rounded-full bg-green-500 flex items-center justify-center shrink-0">
              <Check size={10} className="text-white" />
            </div>
          </div>
          <div>
            <label className="text-xs font-semibold text-slate-600 dark:text-slate-400">WhatsApp (opcional)</label>
            <div className="flex items-center mt-1.5 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl px-4 py-3 gap-2">
              <span className="text-slate-500 text-sm">+54</span>
              <input
                type="tel"
                value={form.contactoWhatsapp}
                onChange={e => setForm(f => ({ ...f, contactoWhatsapp: e.target.value.replace(/\D/g, '') }))}
                placeholder="Número sin 0 ni 15"
                className="flex-1 bg-transparent text-sm outline-none text-slate-900 dark:text-white"
              />
            </div>
          </div>
        </div>

        {error && (
          <div className="flex items-center gap-2 text-red-500 text-sm bg-red-50 dark:bg-red-500/10 rounded-xl px-4 py-3">
            <AlertCircle size={16} />
            {error}
          </div>
        )}
      </div>
    </div>
  );
};

// ─── Mis Productos Screen ─────────────────────────────────────────────────
const MisProductosScreen = () => {
  const [productos, setProductos] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [actionLoading, setActionLoading] = React.useState(null);

  const limits = { usuario: { usado: 3, nuevo: 0 }, emprendimiento: { usado: 10, nuevo: 5 }, empresa: { usado: 999, nuevo: 3 } };
  const roleLimits = limits[userRole] || limits.usuario;

  React.useEffect(() => {
    const load = async () => {
      try {
        const res = await apiFetch(`${API_BASE}/ofertas?vendedorId=${firebaseUser.uid}`, { authRequired: true });
        if (res.ok) setProductos(await res.json());
      } catch { /* silent */ }
      finally { setLoading(false); }
    };
    load();
  }, []);

  const usados = productos.filter(p => p.condicion === 'usado');
  const nuevos = productos.filter(p => p.condicion === 'nuevo');
  const activos = productos.filter(p => p.activa !== false);

  const toggleActiva = async (p) => {
    setActionLoading(p.id);
    try {
      const res = await apiFetch(`${API_BASE}/ofertas`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: p.id, activa: !p.activa }),
        authRequired: true,
      });
      if (res.ok) {
        const updated = await res.json();
        setProductos(prev => prev.map(x => x.id === p.id ? updated : x));
      }
    } finally { setActionLoading(null); }
  };

  const eliminar = async (p) => {
    if (!window.confirm(`¿Eliminar "${p.titulo}"?`)) return;
    setActionLoading(p.id);
    try {
      const res = await apiFetch(`${API_BASE}/ofertas?id=${p.id}`, { method: 'DELETE', authRequired: true });
      if (res.ok) setProductos(prev => prev.filter(x => x.id !== p.id));
    } finally { setActionLoading(null); }
  };

  const LimitBar = ({ label, count, max, color }) => (
    <div className="flex-1">
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs text-slate-500 dark:text-slate-400">{label}</span>
        <span className={`text-xs font-bold ${count >= max ? 'text-red-500' : 'text-slate-700 dark:text-white'}`}>
          {count}/{max === 999 ? '∞' : max}
        </span>
      </div>
      <div className="h-1.5 bg-slate-100 dark:bg-white/10 rounded-full">
        <div className={`h-1.5 rounded-full transition-all ${color}`}
          style={{ width: `${max === 999 ? 10 : Math.min(100, (count / max) * 100)}%` }} />
      </div>
    </div>
  );

  const ProductRow = ({ p }) => {
    const isLoading = actionLoading === p.id;
    const foto = p.fotos?.[0];
    return (
      <div className={`flex items-center gap-3 p-3 rounded-2xl border transition-all ${p.activa !== false ? 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10' : 'bg-slate-50 dark:bg-white/3 border-slate-100 dark:border-white/5 opacity-70'}`}>
        <div className="w-14 h-14 rounded-xl bg-slate-100 dark:bg-white/10 overflow-hidden shrink-0">
          {foto ? <img src={foto} className="w-full h-full object-cover" alt="" /> : <Package size={24} className="text-slate-300 m-auto mt-4" />}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold text-slate-900 dark:text-white truncate">{p.titulo}</p>
          <div className="flex items-center gap-2 mt-1">
            {p.precio && <span className="text-xs font-semibold text-brand">${Number(p.precio).toLocaleString()}</span>}
            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${p.condicion === 'nuevo' ? 'bg-amber-100 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400' : 'bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-400'}`}>
              {p.condicion === 'nuevo' ? 'Nuevo' : 'Usado'}
            </span>
            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${p.activa !== false ? 'bg-green-100 text-green-700 dark:bg-green-500/20 dark:text-green-400' : 'bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-400'}`}>
              {p.activa !== false ? 'Activo' : 'Pausado'}
            </span>
          </div>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          <button
            onClick={() => toggleActiva(p)}
            disabled={isLoading}
            className="w-8 h-8 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center hover:bg-slate-200 dark:hover:bg-white/15 transition-colors"
            title={p.activa !== false ? 'Pausar' : 'Activar'}
          >
            {isLoading ? <Loader2 size={14} className="animate-spin text-slate-400" /> : p.activa !== false ? <Pause size={14} className="text-slate-600 dark:text-slate-300" /> : <Play size={14} className="text-green-500" />}
          </button>
          <button
            onClick={() => eliminar(p)}
            disabled={isLoading}
            className="w-8 h-8 rounded-xl bg-red-50 dark:bg-red-500/10 flex items-center justify-center hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors"
            title="Eliminar"
          >
            <Trash2 size={14} className="text-red-500" />
          </button>
        </div>
      </div>
    );
  };

