useEffect(() => {
  if (!showChat || !firebaseUser) return;
  const tiendaId = showChat.id;
  const load = async () => {
    try {
      const res = await apiFetch(`${API_BASE}/messages?tiendaId=${tiendaId}`, { authRequired: true });
