        text: m.text,
        attachment: m.attachment || null,
        time: tiempoRelativo(m.ts),
        ts: m.ts,
      }));
      setChatHistories(prev => ({ ...prev, [key]: formatted }));
      // Update conversation metadata with latest message
      const last = formatted[formatted.length - 1];
      if (last) {
        setChatConversations(prev => ({
          ...prev,
          [key]: { ...(prev[key] || { id: tiendaId, tienda: showChat.tienda, foto: showChat.foto, telefono: showChat.telefono }), lastMsg: last.attachment ? `📦 ${last.attachment.titulo}` : last.text, lastTime: last.ts, unread: 0 },
        }));
      }
    } catch { /* silencioso */ }
  };
  load();
  const t = setInterval(load, 4000);
  return () => clearInterval(t);
}, [showChat?.id, firebaseUser]);

