      const res = await apiFetch(`${API_BASE}/messages?storeInbox=1&storeId=${tienda.id}`, { authRequired: true });
      if (!res.ok) return;
      const data = await res.json();
      setStoreConvos(data.conversations || []);
      // Update selected convo messages if open
      if (selectedConvo) {
        const updated = (data.conversations || []).find(c => c.key === selectedConvo.key);
        if (updated) setSelectedConvo(prev => ({ ...prev, messages: updated.messages }));
      }
    } catch { /* silencioso */ }
  };
  load();
  const iv = setInterval(load, 8000);
  return () => clearInterval(iv);
}, [tienda?.id, selectedConvo?.key]);

// Scroll to bottom when convo messages change
useEffect(() => {
  storeConvoEndRef.current?.scrollIntoView({ behavior: 'smooth' });
}, [selectedConvo?.messages?.length]);

