    if (!iso) return '';
    const d = new Date(iso);
    const now = new Date();
    const diffDays = Math.floor((now - d) / 86400000);
    if (diffDays === 0) return d.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' });
    if (diffDays === 1) return 'Ayer';
    return d.toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit' });
  };

  if (selectedConvo) {
    const msgs = selectedConvo.messages || [];
    return (
      <div className="flex flex-col h-screen bg-slate-50 dark:bg-slate-950">
        <StorePageHeader
          title={selectedConvo.partnerUid ? `Usuario ${selectedConvo.partnerUid.slice(0, 8)}…` : 'Conversación'}
          onBack={() => setSelectedConvo(null)}
        />
        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3 pb-28 lg:pb-6">
          {msgs.length === 0 && (
            <p className="text-center text-slate-400 text-sm py-10">Sin mensajes aún</p>
          )}
          {msgs.map((msg) => {
            const isStore = String(msg.from) === storeId;
            return (
              <div key={msg.id} className={`flex ${isStore ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[75%] px-4 py-2.5 rounded-2xl text-sm leading-relaxed ${isStore ? 'bg-brand text-white rounded-br-md' : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded-bl-md shadow-sm'}`}>
                  {msg.attachment?.type === 'product' && (
                    <div className="mb-2 p-2 rounded-xl bg-white/20 dark:bg-black/20 flex items-center gap-2">
                      {msg.attachment.imagen && <img src={msg.attachment.imagen} alt="" className="w-10 h-10 rounded-lg object-cover shrink-0" />}
                      <div className="min-w-0">
                        <p className="text-xs font-semibold truncate">{msg.attachment.titulo}</p>
                        {msg.attachment.precio != null && <p className="text-xs opacity-70">${Number(msg.attachment.precio).toLocaleString()}</p>}
                      </div>
                    </div>
                  )}
                  {msg.text && <span>{msg.text}</span>}
                  <p className={`text-[10px] mt-1 ${isStore ? 'text-white/60' : 'text-slate-400'}`}>{formatTime(msg.ts)}</p>
                </div>
              </div>
            );
          })}
          <div ref={storeConvoEndRef} />
        </div>
        {/* Input */}
        <div className="bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-white/8 px-4 py-3 flex items-center gap-3" style={{ paddingBottom: 'max(12px, env(safe-area-inset-bottom))' }}>
          <input
            type="text"
            value={storeChatMsg}
            onChange={e => setStoreChatMsg(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && sendStoreMsg()}
            placeholder="Escribí tu mensaje..."
            className="flex-1 bg-slate-100 dark:bg-white/8 rounded-2xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-brand dark:text-white dark:placeholder:text-slate-500"
          />
          <button
            onClick={sendStoreMsg}
            disabled={!storeChatMsg.trim() || storeChatSending}
            className="w-10 h-10 rounded-xl bg-brand flex items-center justify-center text-white disabled:opacity-40 transition-opacity shrink-0"
          >
            {storeChatSending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-28 lg:pb-8">
      <StorePageHeader title="Mensajes" />
      {storeConvos.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-24 gap-4 text-slate-400">
          <MessageSquare className="w-12 h-12 opacity-30" />
          <p className="text-sm font-medium">Todavía no recibiste mensajes</p>
          <p className="text-xs text-center max-w-xs">Cuando un cliente te escriba desde un producto o tu tienda, aparecerá acá</p>
        </div>
      ) : (
        <div className="divide-y divide-slate-100 dark:divide-white/6">
          {storeConvos.map((convo) => {
            const last = convo.lastMessage;
            const isFromStore = last && String(last.from) === storeId;
            return (
              <button
                key={convo.key}
                onClick={() => setSelectedConvo(convo)}
                className="w-full flex items-center gap-4 px-4 lg:px-6 py-4 hover:bg-slate-100 dark:hover:bg-white/5 transition-colors text-left"
              >
                <div className="w-11 h-11 rounded-2xl bg-brand/10 dark:bg-brand/15 flex items-center justify-center shrink-0">
                  <MessageSquare className="w-5 h-5 text-brand" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-2 mb-0.5">
                    <p className="font-semibold text-sm text-slate-900 dark:text-white truncate">
                      Cliente {convo.partnerUid?.slice(0, 8)}…
                    </p>
                    <span className="text-[10px] text-slate-400 shrink-0">{formatTime(last?.ts)}</span>
                  </div>
                  <p className="text-xs text-slate-500 dark:text-slate-400 truncate">
                    {isFromStore && <span className="text-brand mr-1">Vos:</span>}
                    {last?.attachment?.type === 'product' ? `📦 ${last.attachment.titulo}` : last?.text || 'Sin mensajes'}
                  </p>
                  <p className="text-[10px] text-slate-400 mt-0.5">{convo.count} mensaje{convo.count !== 1 ? 's' : ''}</p>
                </div>
                <ChevronRight className="w-4 h-4 text-slate-300 dark:text-slate-600 shrink-0" />
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
};

