const displayedTiendas = mapCat ? baseTiendas.filter(t => t.rubro === mapCat) : baseTiendas;
const mapCatOptions = React.useMemo(() => {
  const counts = {};
  baseTiendas.forEach(t => { if (t.rubro) counts[t.rubro] = (counts[t.rubro] || 0) + 1; });
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([rubro, count]) => ({ rubro, count }));
