      <span style={{ fontSize: 14, fontWeight: 700, color: txt, ...F.text }}>
        {displayedTiendas.length} tienda{displayedTiendas.length !== 1 ? 's' : ''}{mapCat ? ` · ${mapCat}` : ''}
      </span>
      <button onClick={() => setListOpen(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: txtM, display: 'flex' }}>
