          No hay tiendas{mapCat ? ` de ${mapCat}` : ''} en esta zona
        </div>
      )}
      {displayedTiendas.map(t => {
        const dist = userPos ? (() => {
          const R = 6371; const dLat = (t.lat - userPos[0]) * Math.PI / 180; const dLng = (t.lng - userPos[1]) * Math.PI / 180;
          const a = Math.sin(dLat/2)**2 + Math.cos(userPos[0]*Math.PI/180)*Math.cos(t.lat*Math.PI/180)*Math.sin(dLng/2)**2;
          const d = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
          return d < 1 ? `${Math.round(d*1000)}m` : `${d.toFixed(1)}km`;
        })() : null;
        return (
          <button
            key={t.id}
            onClick={() => { handleSelect(t); setListOpen(false); }}
            style={{
              width: '100%', textAlign: 'left', display: 'flex', alignItems: 'center', gap: 12,
