// ─── Ventaja Filter Bar ───────────────────────────────────────────────────────
const VentajaFilterBar = ({ filtroVentaja, setFiltroVentaja }) => {
  const scrollRef = useRef(null);
  const [canScrollLeft,  setCanScrollLeft]  = React.useState(false);
  const [canScrollRight, setCanScrollRight] = React.useState(false);
  const checkScroll = () => {
    const el = scrollRef.current; if (!el) return;
    setCanScrollLeft(el.scrollLeft > 4);
    setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
  };
  useEffect(() => {
    const el = scrollRef.current; if (!el) return;
    checkScroll();
    el.addEventListener('scroll', checkScroll);
    const ro = new ResizeObserver(checkScroll); ro.observe(el);
    return () => { el.removeEventListener('scroll', checkScroll); ro.disconnect(); };
  }, []);
  const items = [{ id: null, label: 'Todas', Icon: null }, ...Object.entries(VENTAJA_CONFIG).map(([id, v]) => ({ id, label: v.label, Icon: v.Icon }))];
  const btnClass = (active) => `shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${
    active ? 'bg-slate-900 dark:bg-brand text-white shadow-sm' : 'bg-slate-100 dark:bg-white/8 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/12'
  }`;
  return (
    <div className="relative w-full min-w-0 overflow-hidden flex items-center">
      <div ref={scrollRef} className="flex gap-1.5 overflow-x-auto px-4 lg:px-8 py-2 select-none w-full min-w-0 no-scrollbar"
        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
        {items.map(f => (
          <button key={String(f.id)} onClick={() => setFiltroVentaja(f.id)} className={btnClass(filtroVentaja === f.id)}>
            {f.Icon && <f.Icon className="w-3.5 h-3.5" />}
            {f.label}
          </button>
        ))}
      </div>
      {canScrollLeft && (
        <button onClick={() => scrollRef.current?.scrollBy({ left: -160, behavior: 'smooth' })}
          className="absolute left-0 flex items-center justify-center w-8 h-full bg-gradient-to-r from-white dark:from-slate-900 to-transparent text-slate-400 hover:text-slate-600 transition-colors">
          <ChevronLeft className="w-4 h-4" />
        </button>
      )}
      {canScrollRight && (
        <button onClick={() => scrollRef.current?.scrollBy({ left: 160, behavior: 'smooth' })}
          className="absolute right-0 flex items-center justify-center w-8 h-full bg-gradient-to-l from-white dark:from-slate-900 to-transparent text-slate-400 hover:text-slate-600 transition-colors">
          <ChevronRight className="w-4 h-4" />
        </button>
      )}
    </div>
  );
};

