const SEARCH_CONTEXT_CONFIG = {
  // 'hamburguesa': { quickFilters: ['abierto', 'envio'], sortDefault: 'distancia' },
};

const TodasOfertasScreen = ({ searchQuery: initialQuery = '' }) => {
  const [ofertaSearch, setOfertaSearch] = React.useState(initialQuery);
  const [filtroVentaja, setFiltroVentaja] = React.useState(null);
  const [filtroCategoria, setFiltroCategoria] = React.useState(null);
  const [viewMode, setViewMode] = React.useState(() => localStorage.getItem('lokal-view-ofertas') || 'grid');
  const toggleView = () => setViewMode(m => { const n = m === 'list' ? 'grid' : 'list'; localStorage.setItem('lokal-view-ofertas', n); return n; });
  const [storeCtx] = React.useState(() => ofertasStoreFilter);

  // Quick filters binarios — alto impacto, cero fricción
  const [qAbierto, setQAbierto] = React.useState(false);
  const [qEnvio,   setQEnvio]   = React.useState(false);
  const [qCerca,   setQCerca]   = React.useState(false);

  // Filtros avanzados (mobile: bottom sheet / desktop: sidebar)
  const [filtersOpen, setFiltersOpen] = React.useState(false);
  const [filtersClosing, setFiltersClosing] = React.useState(false);
  const closeFilters = () => { setFiltersClosing(true); setTimeout(() => { setFiltersClosing(false); setFiltersOpen(false); }, 280); };

  // Ordenamiento
  const [sortBy, setSortBy] = React.useState('relevancia'); // relevancia | precio-asc | precio-desc | distancia

  const isSearchMode = !!ofertaSearch.trim() || !!initialQuery.trim();

  const ofertasActivas = React.useMemo(() => {
    return visibleOfertas.filter(o => {
      if (o.activa === false) return false;
      if (storeCtx && o.tiendaId !== storeCtx.id) return false;
      const q = ofertaSearch.toLowerCase();
      if (q && !o.titulo.toLowerCase().includes(q) && !o.tiendaNombre?.toLowerCase().includes(q) && !o.descripcion?.toLowerCase().includes(q)) return false;
      if (filtroVentaja && o.ventaja !== filtroVentaja) return false;
      if (filtroCategoria) {
        const path = getCategoryPath(o.categoryId, allCategories);
        if (o.categoryId !== filtroCategoria && !path.some(c => c.id === filtroCategoria)) return false;
      }
      // Quick filters
      if (qAbierto) { const t = tiendas.find(t => t.id === o.tiendaId); if (!t || !isStoreOpen(t.horarios)) return false; }
      if (qEnvio)   { if (o.ventaja !== 'disponibilidad' && !o.envio) return false; }
      if (qCerca)   { const t = tiendas.find(t => t.id === o.tiendaId); if (!t?.distancia) return false; }
      return true;
    }).sort((a, b) => {
      if (sortBy === 'precio-asc')  return (a.precio || Infinity) - (b.precio || Infinity);
      if (sortBy === 'precio-desc') return (b.precio || 0) - (a.precio || 0);
      return 0;
    });
  }, [visibleOfertas, storeCtx, ofertaSearch, filtroVentaja, filtroCategoria, qAbierto, qEnvio, qCerca, sortBy]);

  const activeFilterCount = [filtroVentaja, filtroCategoria, qAbierto, qEnvio, qCerca].filter(Boolean).length;

  const QuickToggle = ({ label, Icon, active, onToggle }) => (
    <button onClick={onToggle}
      className={`shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-semibold transition-all ${
        active ? 'bg-slate-900 dark:bg-brand text-white shadow-sm' : 'bg-white dark:bg-white/8 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-white/10 hover:border-primary/40'
      }`}>
      {Icon && <Icon className="w-3.5 h-3.5" />}{label}
    </button>
  );

  const SortSelect = () => (
    <select value={sortBy} onChange={e => setSortBy(e.target.value)}
      className="text-xs font-semibold text-slate-500 dark:text-slate-400 bg-transparent border-none outline-none cursor-pointer">
      <option value="relevancia">Relevancia</option>
      <option value="precio-asc">Menor precio</option>
      <option value="precio-desc">Mayor precio</option>
    </select>
  );

  // Panel de filtros avanzados — reutilizable en mobile (sheet) y desktop (sidebar)
  const FiltersPanel = ({ onClose }) => (
    <div className="flex flex-col gap-5">
      {/* Categoría */}
      <div>
        <p className="text-xs font-bold tracking-widest uppercase text-slate-400 mb-2">Categoría</p>
        <div className="flex flex-wrap gap-2">
          {allCategories.filter(c => !c.parentId).map(c => (
            <button key={c.id} onClick={() => { setFiltroCategoria(filtroCategoria === c.id ? null : c.id); onClose?.(); }}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${
                filtroCategoria === c.id ? 'bg-slate-900 dark:bg-brand text-white' : 'bg-slate-100 dark:bg-white/8 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/12'
              }`}>
              <CategoryIcon categoryId={c.id} size={13} />
              {c.nombre}
            </button>
          ))}
        </div>
      </div>
      {/* Ventaja */}
      <div>
        <p className="text-xs font-bold tracking-widest uppercase text-slate-400 mb-2">Tipo de oferta</p>
        <div className="flex flex-wrap gap-2">
          {Object.entries(VENTAJA_CONFIG).map(([key, v]) => (
            <button key={key} onClick={() => { setFiltroVentaja(filtroVentaja === key ? null : key); onClose?.(); }}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${
                filtroVentaja === key ? `${v.color} text-white` : 'bg-slate-100 dark:bg-white/8 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/12'
              }`}>
              <v.Icon className="w-3.5 h-3.5" />{v.label}
            </button>
          ))}
        </div>
      </div>
      {/* Ordenar */}
      <div>
        <p className="text-xs font-bold tracking-widest uppercase text-slate-400 mb-2">Ordenar por</p>
        <div className="flex flex-col gap-1.5">
          {[['relevancia','Relevancia'],['precio-asc','Menor precio'],['precio-desc','Mayor precio']].map(([val, lbl]) => (
            <button key={val} onClick={() => { setSortBy(val); onClose?.(); }}
              className={`flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-medium text-left transition-all ${
                sortBy === val ? 'bg-slate-900 dark:bg-brand text-white' : 'bg-slate-100 dark:bg-white/8 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/12'
              }`}>
              {sortBy === val && <Check className="w-3.5 h-3.5 shrink-0" />}
              {lbl}
            </button>
          ))}
        </div>
      </div>
      {activeFilterCount > 0 && (
        <button onClick={() => { setFiltroCategoria(null); setFiltroVentaja(null); setSortBy('relevancia'); setQAbierto(false); setQEnvio(false); setQCerca(false); onClose?.(); }}
          className="mt-1 text-sm font-semibold text-rose-500 hover:text-rose-600 text-left">
          Limpiar todos los filtros
        </button>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f7f8fa] dark:bg-[#0a0d16] pb-28 lg:pb-8">
      <PageHeader
        title={isSearchMode ? `"${ofertaSearch || initialQuery}"` : 'Explorar productos'}
        onBack={() => { setOfertasStoreFilter(null); goBack(); }}
        searchInput={<>
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
          <input type="text" value={ofertaSearch} onChange={e => setOfertaSearch(e.target.value)}
            placeholder="Buscar productos o tiendas..."
            className="ui-input w-full pl-9 pr-3 bg-slate-100 dark:bg-white/6 text-sm placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-primary transition-all" />
        </>}
