const tRelated = (() => {
  const q = ofertaSearch.trim().toLowerCase();
  const seen = new Set();
  const add = (arr) => arr.filter(t => { if (seen.has(t.id)) return false; seen.add(t.id); return true; });

  // 1. tiendas con productos en resultados actuales
  const directIds = new Set(ofertasActivas.map(o => o.tiendaId));
  const byProducts = add(tiendas.filter(t => directIds.has(t.id)));

  // 2. extraer categorías de los productos y tiendas directas para expandir
  const relatedCatIds = new Set();
  if (filtroCategoria) relatedCatIds.add(filtroCategoria);
  ofertasActivas.forEach(o => {
    if (o.categoryId) {
      relatedCatIds.add(o.categoryId);
      getCategoryPath(o.categoryId, allCategories).forEach(c => relatedCatIds.add(c.id));
    }
  });
  byProducts.forEach(t => (t.categoryIds || []).forEach(cid => {
    relatedCatIds.add(cid);
    getCategoryPath(cid, allCategories).forEach(c => relatedCatIds.add(c.id));
  }));

  // 3. tiendas que comparten esas categorías aunque no tengan el producto exacto
  const byCat = relatedCatIds.size > 0 ? add(tiendas.filter(t =>
    (t.categoryIds || []).some(cid => relatedCatIds.has(cid))
  )) : [];

  // 4. tiendas que matchean por nombre/rubro/descripción con la búsqueda
  const byProfile = q ? add(tiendas.filter(t =>
    t.nombre?.toLowerCase().includes(q) ||
    t.rubro?.toLowerCase().includes(q) ||
    t.descripcion?.toLowerCase().includes(q) ||
    (t.tags || []).some(tag => tag.toLowerCase().includes(q))
  )) : [];

  return [...byProducts, ...byCat, ...byProfile].slice(0, 12);
})();

