// ── IA: sugerencia de categoría ───────────────────────────────────────────
const AiCategoryButton = ({ titulo, descripcion, attributes, onResult }) => {
  const [loading, setLoading] = React.useState(false);
  const [result, setResult] = React.useState(null);
  const [err, setErr] = React.useState(null);

  const suggest = async () => {
    if (!titulo.trim()) { setErr('Escribí un título primero'); return; }
    setLoading(true); setResult(null); setErr(null);
    try {
      const res = await apiFetch(`${API_BASE}/suggest-category`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ titulo, descripcion, attributes }),
      });
      if (!res.ok) throw new Error('Error al consultar IA');
      const data = await res.json();
      setResult(data);
    } catch (e) { setErr(e.message); }
    finally { setLoading(false); }
  };

  const apply = () => { onResult(result.categoryId); setResult(null); };

  return (
    <div className="flex flex-col items-end gap-1">
      <button type="button" onClick={suggest} disabled={loading || !titulo.trim()}
        className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold bg-violet-100 dark:bg-violet-500/15 text-violet-700 dark:text-violet-400 hover:bg-violet-200 dark:hover:bg-violet-500/25 disabled:opacity-40 transition-all">
        {loading
          ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
          : <Sparkles className="w-3.5 h-3.5" />}
        {loading ? 'Analizando...' : 'Sugerir con IA'}
      </button>
      {err && <p className="text-xs text-rose-500">{err}</p>}
      {result && (
        <div className="flex items-center gap-2 bg-violet-50 dark:bg-violet-500/10 border border-violet-200 dark:border-violet-500/30 rounded-xl px-3 py-2 text-xs">
          <Sparkles className="w-3.5 h-3.5 text-violet-500 shrink-0" />
          <div className="flex-1">
            <span className="font-bold text-violet-700 dark:text-violet-300">{result.categoryId}</span>
            {result.reason && <span className="text-slate-500 dark:text-slate-400 ml-1">— {result.reason}</span>}
            {result.confidence && <span className="ml-1 text-violet-400">({Math.round(result.confidence * 100)}%)</span>}
          </div>
          <button type="button" onClick={apply}
            className="px-2 py-1 bg-violet-600 text-white rounded-lg font-bold hover:bg-violet-500 transition-colors">
            Aplicar
          </button>
          <button type="button" onClick={() => setResult(null)} className="text-slate-400 hover:text-slate-600">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}
    </div>
  );
};

